format_code:
chip esp32

hardware {
    pin led: Output = 2
}

storage log_count: int = 0

setup {
    log_count = log_count + 1
    storage.save("runs", log_count)
    for i in 0..5 { log("init", "step {i}") }
    var msg: string = "Boot #{log_count}"
    log("boot", msg)
}

system_graph.mermaid:
flowchart LR
    u_setup["setup"]
    v_log_count("log_count")
    s_storage{{"storage"}}
    s_log{{"log"}}
    u_setup -->|write| v_log_count
    v_log_count -.->|read| u_setup
    u_setup -->|save| s_storage
    u_setup -->|log| s_log
    classDef task fill:#1f3a4d,stroke:#2B7CB3,color:#e8e8e8;
    classDef timer fill:#33291a,stroke:#d0a83a,color:#f5e9cf;
    classDef machine fill:#2d1f3d,stroke:#7a3ac0,color:#e8e8e8;
    classDef func fill:#26333a,stroke:#5a8fa0,color:#e8e8e8;
